CREATE TABLE `users` (`id` text PRIMARY KEY NOT NULL, `email` text NOT NULL, `display_name` text DEFAULT '观辰用户' NOT NULL, `status` text DEFAULT 'active' NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `users_email_idx` ON `users` (`email`);
CREATE TABLE `birth_profiles` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL REFERENCES `users`(`id`), `alias` text NOT NULL, `gender` text NOT NULL, `calendar_type` text DEFAULT 'solar' NOT NULL, `birth_datetime` text NOT NULL, `place_name` text NOT NULL, `latitude` text, `longitude` text, `timezone` text DEFAULT 'Asia/Shanghai' NOT NULL, `time_precision` text DEFAULT 'minute' NOT NULL, `true_solar_time` integer DEFAULT false NOT NULL, `deleted_at` text, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE `charts` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL REFERENCES `users`(`id`), `birth_profile_id` text NOT NULL REFERENCES `birth_profiles`(`id`), `type` text NOT NULL, `algorithm_version` text NOT NULL, `input_snapshot` text NOT NULL, `result` text NOT NULL, `result_hash` text NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `chart_hash_idx` ON `charts` (`user_id`,`result_hash`);
CREATE TABLE `reports` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL REFERENCES `users`(`id`), `chart_id` text NOT NULL REFERENCES `charts`(`id`), `topic` text NOT NULL, `status` text DEFAULT 'queued' NOT NULL, `content` text, `evidence` text, `prompt_version` text DEFAULT 'report-v1' NOT NULL, `idempotency_key` text NOT NULL, `error_code` text, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `reports_idempotency_idx` ON `reports` (`user_id`,`idempotency_key`);
CREATE TABLE `credit_accounts` (`user_id` text PRIMARY KEY NOT NULL REFERENCES `users`(`id`), `balance` integer DEFAULT 5 NOT NULL, `version` integer DEFAULT 0 NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE `credit_ledger` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL REFERENCES `users`(`id`), `kind` text NOT NULL, `amount` integer NOT NULL, `balance_after` integer NOT NULL, `reference_type` text NOT NULL, `reference_id` text NOT NULL, `idempotency_key` text NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `ledger_idempotency_idx` ON `credit_ledger` (`user_id`,`idempotency_key`);
CREATE TABLE `credit_packages` (`id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `credits` integer NOT NULL, `price_fen` integer NOT NULL, `active` integer DEFAULT true NOT NULL, `sort_order` integer DEFAULT 0 NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE `orders` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL REFERENCES `users`(`id`), `package_id` text NOT NULL REFERENCES `credit_packages`(`id`), `provider` text DEFAULT 'sandbox' NOT NULL, `amount_fen` integer NOT NULL, `credits` integer NOT NULL, `status` text DEFAULT 'pending' NOT NULL, `provider_trade_no` text, `idempotency_key` text NOT NULL, `paid_at` text, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `orders_idempotency_idx` ON `orders` (`user_id`,`idempotency_key`);
CREATE TABLE `payment_events` (`id` text PRIMARY KEY NOT NULL, `provider` text NOT NULL, `event_id` text NOT NULL, `order_id` text REFERENCES `orders`(`id`), `verified` integer DEFAULT false NOT NULL, `payload_hash` text NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `payment_event_idx` ON `payment_events` (`provider`,`event_id`);
